  assert.ok(has('password-spraying','203.0.113.66'));assert.ok(has('brute-force-then-success','user:victim'));assert.ok(has('impossible-travel','user:traveller'));assert.ok(!has('impossible-travel','user:mover'));assert.ok(has('risky-oauth-consent','app:mail-sync'));assert.ok(!has('risky-oauth-consent','app:calendar'));assert.ok(has('idp-change-unauthorized','federation'));assert.ok(has('idp-change-authorized','conditional-access'));
