test('vulnerability catalog cache follows catalog updates: a newer catalog version replaces the cached ranges',t=>{
  const {d,event,ingest,advance}=fixture(t),cat=(id,max)=>event(id,'vulnerability.catalog',{catalog_id:'CACHE-024',source:'synthetic',published_at:'2026-11-11T00:00:00.000Z',entries:[{vuln_id:'CVE-2026-2001',vendor:null,product:'widget suite',product_aliases:[],affected:{min_version:null,min_version_exclusive:null,max_version_exclusive:max,max_version_inclusive:null},fixed_version:max,fixed_by_update:null,cvss:5,kev:false,summary:'synthetic'}]});
  ingest([cat('cache-v1','2.0'),event('cache-inv','software.inventory',{inventory_id:'INV-CACHE',os:{name:'Microsoft Windows 11 Pro',version:'10.0.26200',build:'26200'},software:[{name:'Widget Suite 1.5',vendor:null,version:'1.5',install_date:null,source:'uninstall-registry'}],updates:[],evidence_ref:'SYNTHETIC-CACHE'})]);
  assert.equal(d.softwareVulnerabilities().items[0].vulnerable_count,1);
  advance(60000);ingest([cat('cache-v2','1.2')]);
  assert.equal(d.softwareVulnerabilities().items[0].vulnerable_count,0,'the cached index must be rebuilt for the newer catalog version');
  assert.equal(d.softwareVulnerabilities().catalogs[0].entries,1);
});
test('database survives reopen; migration rerun preserves records; audit rejects modification and detects tampering',()=>{
  const dir=fs.mkdtempSync(path.join(os.tmpdir(),'cg-store-test-')),file=path.join(dir,'test.sqlite');
  let s;
  try {
    s=new Store(file);s.audit('synthetic','test','record');s.close();
    s=new Store(file);s.migrate();assert.equal(s.verifyAudit().checked,1);
    assert.throws(()=>s.run('UPDATE audit SET action=\'changed\''),/audit_append_only/);
    s.db.exec('DROP TRIGGER audit_no_update');s.run('UPDATE audit SET action=\'changed\'');
    assert.equal(s.verifyAudit().valid,false);s.close();s=null;
    assert.throws(()=>new Store(file),/audit_integrity_failure/);
  } finally {s?.close();fs.rmSync(dir,{recursive:true,force:true});}
});
